def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    value = ((v1 - v2) / v2) * 100

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "change": v1 - v2,
            "percentage_change": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
